const { objectType, searchTerm, filterProperty, filterOperator, filterValue, properties, limit } = $.input;
if (!objectType) throw new Error('objectType is required');
const body = { limit: Math.min(limit || 10, 100) };
if (searchTerm) body.query = searchTerm;
if (properties && properties.length > 0) body.properties = properties;
if (filterProperty && filterValue) {
  body.filterGroups = [{
    filters: [{
      propertyName: filterProperty,
      operator: filterOperator || 'EQ',
      value: filterValue
    }]
  }];
}
return body;

const resp = $.steps.searchObjects.response || {};
const results = resp.results || [];
return {
  objects: results.map(o => ({
    id: o.id,
    properties: o.properties || {},
    createdAt: o.createdAt,
    updatedAt: o.updatedAt
  })),
  objectType: $.input.objectType,
  total: resp.total || results.length,
  count: results.length,
  paging: resp.paging || null,
  summary: `Found ${resp.total || results.length} ${$.input.objectType} record${(resp.total || results.length) === 1 ? '' : 's'}`
};
